def experiment_1(seed: int,
                 virtuality: int):
    monitor, lengths, number, maximum_depth = Monitor(), [150, 25], 3000, 1000

    if not path.exists(raw_path + "experiment.retrieval-1.sequences.pkl"):
        print("Produce 3000 DNA sequences for comparable evaluation of different high-quality real-time retrievals:")
        method = SpiderWeb(accessor=load_data(raw_path + "generation-2.special-case.pkl")[0])
        payloads, counts, miss = method.produce(virtuality=virtuality, length=lengths[0],
                                                duplicatable=True, palindromable=True, allow_self_palindrome=False,
                                                need_preorder=True, diversity=number, seed=seed, verbose=True)

        # In the early implementation (before 2024),
        # we used a set to collect randomly generated sequences and remove duplicates in the method.produce function.
        # We noticed that the sequence order resulting from converting a set into a list was not controlled
        # by the random seed we provided and could therefore vary across executions.
        # Since the original implementation had already established a fixed sequence order,
        # regenerating the sequences from scratch could introduce inconsistencies in
        # subsequent similarity calculations and retrieval grouping, both of which depend on sequence indexing.
        # Therefore, for automated reproduction, we verify that the regenerated sequences match the original sequences
        # at the set level and retain the original sequence order for subsequent computational steps.
